package com.gameaggregator.revenueservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.UUID;@Entity @Table(name="revenue_rule_versions",uniqueConstraints=@UniqueConstraint(columnNames={"ruleId","versionNumber"})) public class RevenueRuleVersion{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID ruleId;@Column(nullable=false)public int versionNumber;@Column(nullable=false)public LocalDate effectiveFrom;public LocalDate effectiveTo;@Column(nullable=false)public String calculationMethod;@Column(nullable=false,precision=8,scale=5)public BigDecimal platformShare;@Column(nullable=false,precision=8,scale=5)public BigDecimal studioShare;@Column(nullable=false,precision=8,scale=5)public BigDecimal publisherShare;@Column(nullable=false,precision=8,scale=5)public BigDecimal clientShare;protected RevenueRuleVersion(){}public RevenueRuleVersion(UUID r,int v,LocalDate f,LocalDate t,String m,BigDecimal p,BigDecimal s,BigDecimal u,BigDecimal c){ruleId=r;versionNumber=v;effectiveFrom=f;effectiveTo=t;calculationMethod=m;platformShare=p;studioShare=s;publisherShare=u;clientShare=c;}}